package vn.svframe.svframelib.script.mechanic.misc;import vn.svframe.svframelib.script.mechanic.RawMechanic;import vn.svframe.svframelib.util.configobject.ConfigObject;public class LightningStrikeMechanic extends RawMechanic{public LightningStrikeMechanic(ConfigObject c){super("lightning_strike"+render(c));}private static String render(ConfigObject c){if(c==null||c.getKeys().isEmpty())return "";StringBuilder b=new StringBuilder("{");boolean first=true;for(String k:c.getKeys()){if(!first)b.append(';');first=false;b.append(k).append('=').append(c.getString(k,""));}return b.append('}').toString();}}